  1→import { useEffect, useState, useRef, useCallback, useMemo } from 'react';
  2→import {
  3→  View,
  4→  Text,
  5→  StyleSheet,
  6→  Dimensions,
  7→  TouchableOpacity,
  8→} from 'react-native';
  9→import { useLocalSearchParams, useRouter } from 'expo-router';
 10→import * as Haptics from 'expo-haptics';
 11→import Animated, {
 12→  useSharedValue,
 13→  useAnimatedStyle,
 14→  withTiming,
 15→  runOnJS,
 16→  Easing,
 17→} from 'react-native-reanimated';
 18→import { Gesture, GestureDetector } from 'react-native-gesture-handler';
 19→import { useReaderData } from '@/hooks/useBookData';
 20→import { useReadingProgress, useAutoSaveProgress } from '@/hooks/useReadingProgress';
 21→import { useReaderAudio } from '@/hooks/useReaderAudio';
 22→import { useThemeColors, fonts } from '@/lib/theme';
 23→import { ReaderTopBar } from '@/components/ReaderTopBar';
 24→import { AudioControls } from '@/components/AudioControls';
 25→import { PageRenderer } from '@/components/PageRenderer';
 26→import { SwipePageIndicator } from '@/components/SwipePageIndicator';
 27→import { PageLayer } from '@/components/reader/PageLayer';
 28→import { EdgeTapZones } from '@/components/reader/EdgeTapZones';
 29→import { usePageAnimatedStyle } from '@/hooks/useReaderAnimations';
 30→import { ReaderSkeleton } from '@/components/Skeleton';
 31→import { GestureTutorial, hasSeenGestureTutorial, markGestureTutorialSeen } from '@/components/reader/GestureTutorial';
 32→import type { PageData } from '@/types';
 33→
 34→const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get('window');
 35→const SWIPE_THRESHOLD = SCREEN_HEIGHT * 0.18;
 36→const VELOCITY_THRESHOLD = 500;
 37→
 38→// easeOutExpo bezier — starts fast, decelerates very smoothly (Lenis feel)
 39→const EASE_OUT_EXPO = Easing.bezier(0.16, 1, 0.3, 1);
 40→
 41→// easeOutQuart for snap-back (cancelled swipe) — slightly less dramatic
 42→const EASE_OUT_QUART = Easing.bezier(0.25, 1, 0.5, 1);
 43→
 44→const UI_ANIMATION_DURATION = 300;
 45→
 46→// Maximum number of dots to show before collapsing
 47→const MAX_VISIBLE_DOTS = 7;
 48→
 49→/**
 50→ * Vertical page indicator dots that appear on the right edge.
 51→ * Shows a window of dots around the active page for long books.
 52→ */
 53→function PageDots({
 54→  totalPages,
 55→  activeIndex,
 56→  isVisible,
 57→}: {
 58→  totalPages: number;
 59→  activeIndex: number;
 60→  isVisible: boolean;
 61→}) {
 62→  const containerStyle = useAnimatedStyle(() => ({
 63→    opacity: withTiming(isVisible ? 1 : 0, { duration: UI_ANIMATION_DURATION }),
 64→    transform: [
 65→      { translateX: withTiming(isVisible ? 0 : 8, { duration: UI_ANIMATION_DURATION }) },
 66→    ],
 67→  }));
 68→
 69→  if (totalPages <= 1) return null;
 70→
 71→  // For books with many pages, show a sliding window of dots
 72→  const showAllDots = totalPages <= MAX_VISIBLE_DOTS;
 73→  let startIndex = 0;
 74→  let endIndex = totalPages - 1;
 75→
 76→  if (!showAllDots) {
 77→    const halfWindow = Math.floor(MAX_VISIBLE_DOTS / 2);
 78→    startIndex = Math.max(0, activeIndex - halfWindow);
 79→    endIndex = startIndex + MAX_VISIBLE_DOTS - 1;
 80→    if (endIndex >= totalPages) {
 81→      endIndex = totalPages - 1;
 82→      startIndex = Math.max(0, endIndex - MAX_VISIBLE_DOTS + 1);
 83→    }
 84→  }
 85→
 86→  const dots = [];
 87→  for (let i = startIndex; i <= endIndex; i++) {
 88→    const isActive = i === activeIndex;
 89→    // Scale dots at the edges smaller for a nice fade effect
 90→    const distFromActive = Math.abs(i - activeIndex);
 91→    const isEdgeDot = !showAllDots && (i === startIndex || i === endIndex) && distFromActive > 2;
 92→
 93→    dots.push(
 94→      <View
 95→        key={i}
 96→        style={[
 97→          dotStyles.dot,
 98→          isActive && dotStyles.dotActive,
 99→          isEdgeDot && dotStyles.dotSmall,
100→        ]}
101→      />
102→    );
103→  }
104→
105→  return (
106→    <Animated.View
107→      style={[dotStyles.container, containerStyle]}
108→      pointerEvents="none"
109→    >
110→      {dots}
111→    </Animated.View>
112→  );
113→}
114→
115→const dotStyles = StyleSheet.create({
116→  container: {
117→    position: 'absolute',
118→    right: 12,
119→    top: '50%',
120→    transform: [{ translateY: -50 }],
121→    alignItems: 'center',
122→    gap: 6,
123→    zIndex: 35,
124→  },
125→  dot: {
126→    width: 4,
127→    height: 4,
128→    borderRadius: 2,
129→    backgroundColor: 'rgba(255,255,255,0.25)',
130→  },
131→  dotActive: {
132→    width: 5,
133→    height: 5,
134→    borderRadius: 2.5,
135→    backgroundColor: 'rgba(255,255,255,0.85)',
136→    shadowColor: '#fff',
137→    shadowOffset: { width: 0, height: 0 },
138→    shadowOpacity: 0.4,
139→    shadowRadius: 4,
140→  },
141→  dotSmall: {
142→    width: 3,
143→    height: 3,
144→    borderRadius: 1.5,
145→    opacity: 0.4,
146→  },
147→});
148→
149→export default function ReaderScreen() {
150→  const { id } = useLocalSearchParams<{ id: string }>();
151→  const router = useRouter();
152→  const colors = useThemeColors();
153→  const bookId = id ?? '';
154→
155→  // Data
156→  const { data: readerData, isLoading, error, refetch } = useReaderData(bookId);
157→  const { data: savedProgress } = useReadingProgress(bookId);
158→
159→  // State
160→  const [activeIndex, setActiveIndex] = useState(0);
161→  const [showSettings, setShowSettings] = useState(false);
162→  const [isUIVisible, setIsUIVisible] = useState(true);
163→  const [showTutorial, setShowTutorial] = useState(false);
164→  const progressRestoredRef = useRef(false);
165→  const tutorialCheckedRef = useRef(false);
166→
167→  // Derived
168→  const pages = useMemo(
169→    () => [...(readerData?.pages ?? [])].sort((a, b) => a.pageNumber - b.pageNumber),
170→    [readerData?.pages]
171→  );
172→  const totalPages = pages.length;
173→  const currentPage = pages[activeIndex]?.pageNumber ?? 1;
174→  const pageData: PageData | undefined = pages[activeIndex];
175→  const progressPercent = totalPages > 0 ? ((activeIndex + 1) / totalPages) * 100 : 0;
176→
177→  // Audio
178→  const {
179→    isNarrationActive,
180→    isSoundscapeActive,
181→    narrationState,
182→    soundscapeState,
183→    toggleNarration,
184→    toggleSoundscape,
185→    cleanup,
186→  } = useReaderAudio({ pageData, bookId });
187→
188→  const narrationAssignment = pageData?.assignments?.find((a) => a.audioType === 'narration');
189→  const soundscapeAssignment = pageData?.assignments?.find((a) => a.audioType === 'soundscape');
190→  const narrationUrl = narrationAssignment?.audioUrl || pageData?.narrationUrl;
191→  const soundscapeUrl = soundscapeAssignment?.audioUrl;
192→
193→  // ===============================================================
194→  // REANIMATED GESTURE PAGER
195→  // ===============================================================
196→
197→  const scrollOffset = useSharedValue(0); // continuous, -pageIndex * SCREEN_HEIGHT at rest
198→  const activeIndexShared = useSharedValue(0);
199→  const baseScrollOffset = useSharedValue(0); // captures position at gesture start
200→  const getPageAnimatedStyle = usePageAnimatedStyle(scrollOffset, activeIndexShared);
201→
202→  const updateActiveIndex = useCallback(
203→    (newIndex: number) => {
204→      setActiveIndex(newIndex);
205→      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
206→    },
207→    []
208→  );
209→
210→  const panGesture = Gesture.Pan()
211→    .activeOffsetY([-12, 12])
212→    .onBegin(() => {
213→      // Capture scroll position at gesture start so we can offset from it
214→      baseScrollOffset.value = scrollOffset.value;
215→    })
216→    .onUpdate((e) => {
217→      const totalPgs = totalPages; // captured from JS scope via closure
218→
219→      const rawOffset = baseScrollOffset.value + e.translationY;
220→
221→      // Rubber band at boundaries
222→      const minOffset = -(totalPgs - 1) * SCREEN_HEIGHT; // last page
223→      const maxOffset = 0; // first page
224→
225→      if (rawOffset > maxOffset) {
226→        // Rubber band past first page
227→        scrollOffset.value = maxOffset + (rawOffset - maxOffset) * 0.15;
228→      } else if (rawOffset < minOffset) {
229→        // Rubber band past last page
230→        scrollOffset.value = minOffset + (rawOffset - minOffset) * 0.15;
231→      } else {
232→        scrollOffset.value = rawOffset;
233→      }
234→    })
235→    .onEnd((e) => {
236→      const idx = activeIndexShared.value;
237→      const totalPgs = totalPages;
238→
239→      const swipedUp = e.translationY < -SWIPE_THRESHOLD || e.velocityY < -VELOCITY_THRESHOLD;
240→      const swipedDown = e.translationY > SWIPE_THRESHOLD || e.velocityY > VELOCITY_THRESHOLD;
241→
242→      let destIndex = idx;
243→      if (swipedUp && idx < totalPgs - 1) {
244→        destIndex = idx + 1;
245→      } else if (swipedDown && idx > 0) {
246→        destIndex = idx - 1;
247→      }
248→
249→      const destOffset = -destIndex * SCREEN_HEIGHT;
250→
251→      // Duration adapts to distance remaining + gesture velocity for natural feel.
252→      // Fast swipes arrive quicker; slow/cancelled swipes take standard time.
253→      const distance = Math.abs(destOffset - scrollOffset.value);
254→      const speed = Math.max(Math.abs(e.velocityY), 100);
255→      const duration = Math.min(Math.max((distance / speed) * 1000 * 0.6, 280), 520);
256→
257→      if (destIndex !== idx) {
258→        activeIndexShared.value = destIndex;
259→        runOnJS(updateActiveIndex)(destIndex);
260→      }
261→
262→      // Smooth ease-out settle — the Lenis feel
263→      scrollOffset.value = withTiming(destOffset, {
264→        duration,
265→        easing: destIndex !== idx ? EASE_OUT_EXPO : EASE_OUT_QUART,
266→      });
267→    });
268→
269→  // Tap to toggle UI visibility
270→  const tapGesture = Gesture.Tap()
271→    .maxDuration(250)
272→    .onEnd(() => {
273→      runOnJS(toggleUI)();
274→    });
275→
276→  // Combine gestures - Race allows pan to win when swiping, tap to win on tap
277→  const composedGesture = Gesture.Race(panGesture, tapGesture);
278→
279→  const toggleUI = useCallback(() => {
280→    setIsUIVisible((prev) => {
281→      const newValue = !prev;
282→      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
283→      return newValue;
284→    });
285→  }, []);
286→
287→  // ===============================================================
288→  // PROGRESS
289→  // ===============================================================
290→
291→  useAutoSaveProgress({
292→    bookId,
293→    currentPage,
294→    totalPages,
295→    enabled: !isLoading && totalPages > 0,
296→  });
297→
298→  // Restore reading progress
299→  useEffect(() => {
300→    if (progressRestoredRef.current || isLoading || !readerData) return;
301→
302→    if (savedProgress?.currentPage && savedProgress.currentPage > 1 && savedProgress.currentPage <= totalPages) {
303→      const idx = pages.findIndex((p) => p.pageNumber === savedProgress.currentPage);
304→      if (idx > 0) {
305→        setActiveIndex(idx);
306→        activeIndexShared.value = idx;
307→        scrollOffset.value = -idx * SCREEN_HEIGHT;
308→      }
309→    }
310→    progressRestoredRef.current = true;
311→  }, [savedProgress, isLoading, readerData, totalPages, pages, activeIndexShared, scrollOffset]);
312→
313→  // ===============================================================
314→  // GESTURE TUTORIAL (FTUE)
315→  // ===============================================================
316→
317→  useEffect(() => {
318→    if (tutorialCheckedRef.current || isLoading) return;
319→
320→    const checkTutorial = async () => {
321→      const hasSeen = await hasSeenGestureTutorial();
322→      if (!hasSeen) {
323→        setShowTutorial(true);
324→      }
325→      tutorialCheckedRef.current = true;
326→    };
327→
328→    checkTutorial();
329→  }, [isLoading]);
330→
331→  const handleTutorialComplete = useCallback(() => {
332→    setShowTutorial(false);
333→    markGestureTutorialSeen();
334→  }, []);
335→
336→  // ===============================================================
337→  // CLEANUP
338→  // ===============================================================
339→
340→  // Cleanup on unmount
341→  useEffect(() => {
342→    return () => {
343→      cleanup();
344→    };
345→    // eslint-disable-next-line react-hooks/exhaustive-deps
346→  }, []);
347→
348→  const handleClose = useCallback(() => {
349→    cleanup();
350→    router.back();
351→  }, [router, cleanup]);
352→
353→  // ===============================================================
354→  // EDGE TAP NAVIGATION
355→  // ===============================================================
356→
357→  const goToPreviousPage = useCallback(() => {
358→    if (activeIndex > 0) {
359→      const newIndex = activeIndex - 1;
360→      setActiveIndex(newIndex);
361→      activeIndexShared.value = newIndex;
362→      scrollOffset.value = withTiming(-newIndex * SCREEN_HEIGHT, {
363→        duration: 400,
364→        easing: EASE_OUT_EXPO,
365→      });
366→      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
367→    }
368→  }, [activeIndex, activeIndexShared, scrollOffset]);
369→
370→  const goToNextPage = useCallback(() => {
371→    if (activeIndex < totalPages - 1) {
372→      const newIndex = activeIndex + 1;
373→      setActiveIndex(newIndex);
374→      activeIndexShared.value = newIndex;
375→      scrollOffset.value = withTiming(-newIndex * SCREEN_HEIGHT, {
376→        duration: 400,
377→        easing: EASE_OUT_EXPO,
378→      });
379→      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
380→    }
381→  }, [activeIndex, totalPages, activeIndexShared, scrollOffset]);
382→
383→  // Animated styles for UI visibility
384→  const topBarAnimatedStyle = useAnimatedStyle(() => ({
385→    opacity: withTiming(isUIVisible ? 1 : 0, { duration: UI_ANIMATION_DURATION }),
386→  }));
387→
388→  const audioControlsAnimatedStyle = useAnimatedStyle(() => ({
389→    opacity: withTiming(isUIVisible ? 1 : 0, { duration: UI_ANIMATION_DURATION }),
390→  }));
391→
392→  const tapHintAnimatedStyle = useAnimatedStyle(() => ({
393→    opacity: withTiming(isUIVisible ? 0 : 0.4, { duration: UI_ANIMATION_DURATION }),
394→  }));
395→
396→  // ===============================================================
397→  // VISIBLE PAGES (virtualization window of +/-1)
398→  // Optimized: O(1) slice instead of O(n) filter + indexOf
399→  // ===============================================================
400→
401→  const visiblePages = useMemo(() => {
402→    const start = Math.max(0, activeIndex - 1);
403→    const end = Math.min(pages.length - 1, activeIndex + 1);
404→    const result: { page: typeof pages[0]; index: number }[] = [];
405→    for (let i = start; i <= end; i++) {
406→      result.push({ page: pages[i], index: i });
407→    }
408→    return result;
409→  }, [pages, activeIndex]);
410→
411→  // ===============================================================
412→  // RENDER
413→  // ===============================================================
414→
415→  if (isLoading) {
416→    return <ReaderSkeleton />;
417→  }
418→
419→  if (error || !readerData) {
420→    return (
421→      <View style={[styles.centered, { backgroundColor: colors.readerBg }]}>
422→        <Text style={[styles.errorTitle, { color: colors.error, fontFamily: fonts.sans }]}>
423→          Oops!
424→        </Text>
425→        <Text style={[styles.errorText, { color: colors.readerTextSecondary, fontFamily: fonts.sans }]}>
426→          {error?.message || 'Book not found'}
427→        </Text>
428→        <View style={styles.errorButtonsContainer}>
429→          <TouchableOpacity
430→            style={[styles.primaryButton, { backgroundColor: colors.readerProgressBarFill }]}
431→            onPress={() => refetch()}
432→            activeOpacity={0.8}
433→          >
434→            <Text style={[styles.primaryButtonText, { color: colors.readerBg, fontFamily: fonts.sans }]}>
435→              Try Again
436→            </Text>
437→          </TouchableOpacity>
438→          <TouchableOpacity
439→            style={[styles.secondaryButton, { borderColor: colors.readerTextSecondary }]}
440→            onPress={() => router.back()}
441→            activeOpacity={0.8}
442→          >
443→            <Text style={[styles.secondaryButtonText, { color: colors.readerTextSecondary, fontFamily: fonts.sans }]}>
444→              Go Back
445→            </Text>
446→          </TouchableOpacity>
447→        </View>
448→      </View>
449→    );
450→  }
451→
452→  return (
453→    <View style={[styles.container, { backgroundColor: colors.readerBg }]}>
454→      <GestureDetector gesture={composedGesture}>
455→        <View style={styles.pagerContainer}>
456→          {visiblePages.map(({ page, index }) => (
457→            <PageLayer
458→              key={page.id}
459→              page={page}
460→              pageIndex={index}
461→              activeIndex={activeIndex}
462→              narrationTimestamps={page.narrationTimestamps ?? null}
463→              currentPositionMs={narrationState.positionMs}
464→              isNarrationPlaying={isNarrationActive && narrationState.isPlaying}
465→              usePageAnimatedStyle={getPageAnimatedStyle}
466→            />
467→          ))}
468→        </View>
469→      </GestureDetector>
470→
471→      {/* Vertical page dots - right edge */}
472→      <PageDots
473→        totalPages={totalPages}
474→        activeIndex={activeIndex}
475→        isVisible={isUIVisible}
476→      />
477→
478→      {/* Floating UI - Top bar */}
479→      <Animated.View
480→        style={[styles.topBarContainer, topBarAnimatedStyle]}
481→        pointerEvents={isUIVisible ? 'auto' : 'none'}
482→      >
483→        <ReaderTopBar
484→          progressPercent={progressPercent}
485→          currentPage={currentPage}
486→          totalPages={totalPages}
487→          onClose={handleClose}
488→          onSettings={() => setShowSettings(true)}
489→        />
490→      </Animated.View>
491→
492→      {/* Floating UI - Audio controls */}
493→      <Animated.View
494→        style={[styles.audioControlsContainer, audioControlsAnimatedStyle]}
495→        pointerEvents={isUIVisible ? 'auto' : 'none'}
496→      >
497→        <AudioControls
498→          hasNarration={!!narrationUrl}
499→          hasSoundscape={!!soundscapeUrl}
500→          isNarrationPlaying={isNarrationActive && narrationState.isPlaying}
501→          isSoundscapePlaying={isSoundscapeActive && soundscapeState.isPlaying}
502→          onToggleNarration={toggleNarration}
503→          onToggleSoundscape={toggleSoundscape}
504→        />
505→      </Animated.View>
506→
507→      <SwipePageIndicator visible={isUIVisible && activeIndex === 0 && totalPages > 1} />
508→
509→      {/* Edge Tap Zones - only visible when UI is hidden */}
510→      {!isUIVisible && (
511→        <EdgeTapZones
512→          onPrevious={goToPreviousPage}
513→          onNext={goToNextPage}
514→          isVisible={!isUIVisible}
515→        />
516→      )}
517→
518→      {/* Tap hint when UI is hidden */}
519→      <Animated.View style={[styles.tapHintContainer, tapHintAnimatedStyle]} pointerEvents="none">
520→        <View style={styles.tapHintPill}>
521→          <Text style={styles.tapHintText}>
522→            Tap to show controls
523→          </Text>
524→        </View>
525→      </Animated.View>
526→
527→      <GestureTutorial
528→        visible={showTutorial}
529→        onComplete={handleTutorialComplete}
530→      />
531→    </View>
532→  );
533→}
534→
