 1→import React, { useCallback, useMemo } from 'react';
 2→import { View, Dimensions } from 'react-native';
 3→import { useSharedValue, withSpring, runOnJS } from 'react-native-reanimated';
 4→import { Gesture, GestureDetector } from 'react-native-gesture-handler';
 5→import { useReader } from '@/contexts/ReaderContext';
 6→import { usePageAnimatedStyle } from '@/hooks/useReaderAnimations';
 7→import { PageLayer } from './PageLayer';
 8→import type { PageData } from '@/types';
 9→
10→const { height: SCREEN_HEIGHT } = Dimensions.get('window');
11→const SWIPE_THRESHOLD = SCREEN_HEIGHT * 0.18;
12→const VELOCITY_THRESHOLD = 500;
13→
14→const SPRING_CONFIG = {
15→  damping: 22,
16→  stiffness: 200,
17→  mass: 1,
18→};
19→
20→export function ReaderContainer() {
21→  const { pages, activeIndex, goToPage } = useReader();
22→
23→  const translateY = useSharedValue(0);
24→  const activeIndexShared = useSharedValue(activeIndex);
25→
26→  const getPageAnimatedStyle = usePageAnimatedStyle(translateY, activeIndexShared);
27→
28→  const totalPages = pages.length;
29→
30→  const updateIndex = useCallback(
31→    (newIndex: number) => {
32→      goToPage(newIndex);
33→    },
34→    [goToPage]
35→  );
36→
37→  const panGesture = Gesture.Pan()
38→    .activeOffsetY([-15, 15])
39→    .onUpdate((e) => {
40→      const idx = activeIndexShared.value;
41→      if (idx === 0 && e.translationY > 0) {
42→        translateY.value = e.translationY * 0.3;
43→      } else if (idx === totalPages - 1 && e.translationY < 0) {
44→        translateY.value = e.translationY * 0.3;
45→      } else {
46→        translateY.value = e.translationY;
47→      }
48→    })
49→    .onEnd((e) => {
50→      const idx = activeIndexShared.value;
51→      const swipedUp = e.translationY < -SWIPE_THRESHOLD || e.velocityY < -VELOCITY_THRESHOLD;
52→      const swipedDown = e.translationY > SWIPE_THRESHOLD || e.velocityY > VELOCITY_THRESHOLD;
53→
54→      if (swipedUp && idx < totalPages - 1) {
55→        activeIndexShared.value = idx + 1;
56→        translateY.value = withSpring(0, SPRING_CONFIG);
57→        runOnJS(updateIndex)(idx + 1);
58→      } else if (swipedDown && idx > 0) {
59→        activeIndexShared.value = idx - 1;
60→        translateY.value = withSpring(0, SPRING_CONFIG);
61→        runOnJS(updateIndex)(idx - 1);
62→      } else {
63→        translateY.value = withSpring(0, SPRING_CONFIG);
64→      }
65→    });
66→
67→  const visiblePages = useMemo(() => {
68→    return pages.filter((_: PageData, i: number) => Math.abs(i - activeIndex) <= 1);
69→  }, [pages, activeIndex]);
70→
71→  React.useEffect(() => {
72→    activeIndexShared.value = activeIndex;
73→  }, [activeIndex, activeIndexShared]);
74→
75→  return (
76→    <GestureDetector gesture={panGesture}>
77→      <View style={{ flex: 1 }}>
78→        {visiblePages.map((page: PageData) => {
79→          const pageIndex = pages.indexOf(page);
80→          return (
81→            <PageLayer
82→              key={page.id}
83→              page={page}
84→              pageIndex={pageIndex}
85→              activeIndex={activeIndex}
86→              narrationTimestamps={page.narrationTimestamps ?? null}
87→              currentPositionMs={0}
88→              isNarrationPlaying={false}
89→              usePageAnimatedStyle={getPageAnimatedStyle}
90→            />
91→          );
92→        })}
93→      </View>
94→    </GestureDetector>
95→  );
96→}
