 31→class _PageRendererState extends State<PageRenderer> {
 32→  Size? _sourceImageSize;
 33→
 34→  @override
 35→  void initState() {
 36→    super.initState();
 37→    _resolveImageDimensions();
 38→  }
 39→
 40→  @override
 41→  void didUpdateWidget(covariant PageRenderer oldWidget) {
 42→    super.didUpdateWidget(oldWidget);
 43→    if (oldWidget.page.imageUrl != widget.page.imageUrl) {
 44→      _sourceImageSize = null;
 45→      _resolveImageDimensions();
 46→    }
 47→  }
 48→
 49→  Future<void> _resolveImageDimensions() async {
 50→    final imageUrl = widget.page.imageUrl;
 51→    if (imageUrl == null || imageUrl.isEmpty) {
 52→      return;
 53→    }
 54→
 55→    final completer = Completer<Size>();
 56→    final stream = CachedNetworkImageProvider(
 57→      imageUrl,
 58→      cacheManager: ResilientCacheManager.instance,
 59→    ).resolve(const ImageConfiguration());
 60→    late final ImageStreamListener listener;
 61→    listener = ImageStreamListener(
 62→      (image, _) {
 63→        if (!completer.isCompleted) {
 64→          completer.complete(
 65→            Size(image.image.width.toDouble(), image.image.height.toDouble()),
 66→          );
 67→        }
 68→        stream.removeListener(listener);
 69→      },
 70→      onError: (_, __) {
 71→        if (!completer.isCompleted) {
 72→          completer.complete(Size.zero);
 73→        }
 74→        stream.removeListener(listener);
 75→      },
 76→    );
 77→
 78→    stream.addListener(listener);
 79→    final size = await completer.future;
 80→    if (!mounted) {
 81→      return;
 82→    }
 83→    setState(() {
 84→      _sourceImageSize = size;
 85→    });
 86→  }
