 94→        (page.textContent ?? '').trim().isNotEmpty &&
 95→        (page.imageUrl ?? '').isNotEmpty;
 96→
 97→    return LayoutBuilder(
 98→      builder: (context, constraints) {
 99→        final container = Size(constraints.maxWidth, constraints.maxHeight);
100→        final sourceImageSize = _sourceImageSize;
101→        final imageRect = hasOverlay && sourceImageSize != null
102→            ? computeContainedImageRect(
103→                container: container,
104→                sourceImage: sourceImageSize,
105→              )
106→            : Rect.fromLTWH(0, 0, container.width, container.height);
107→
108→        final activeWordIndex = computeActiveWordIndex(
