  1→import React, { createContext, useContext, useState, useCallback, useMemo, useEffect, useRef, ReactNode } from 'react';
  2→import { useRouter } from 'expo-router';
  3→import * as Haptics from 'expo-haptics';
  4→import { useSharedValue } from 'react-native-reanimated';
  5→import { useReaderData } from '@/hooks/useBookData';
  6→import { useReadingProgress, useAutoSaveProgress } from '@/hooks/useReadingProgress';
  7→import { useAudioPlayer } from '@/hooks/useAudioPlayer';
  8→import { useLocalPreferences } from '@/hooks/useLocalPreferences';
  9→import { usePageAnimatedStyle } from '@/hooks/useReaderAnimations';
 10→import type { PageData, ReaderResponse } from '@/types';
 11→
 12→type AudioPlayerState = {
 13→  isPlaying: boolean;
 14→  positionMs: number;
 15→  durationMs: number;
 16→};
 17→
 18→interface ReaderContextValue {
 19→  // Page state
 20→  activeIndex: number;
 21→  totalPages: number;
 22→  currentPage: number;
 23→  progressPercent: number;
 24→  pages: PageData[];
 25→
 26→  // Audio state
 27→  isNarrationActive: boolean;
 28→  isSoundscapeActive: boolean;
 29→  narrationState: AudioPlayerState;
 30→  soundscapeState: AudioPlayerState;
 31→
 32→  // UI visibility state
 33→  isUIVisible: boolean;
 34→
 35→  // Actions
 36→  goToPage: (index: number) => void;
 37→  toggleNarration: () => void;
 38→  toggleSoundscape: () => void;
 39→  handleClose: () => void;
 40→  toggleUI: () => void;
 41→  showUI: () => void;
 42→  hideUI: () => void;
 43→
 44→  // Data
 45→  readerData: ReaderResponse | undefined;
 46→  isLoading: boolean;
 47→  error: Error | null;
 48→
 49→  // Utility
 50→  visiblePageIndices: number[];
 51→
 52→  // Internal (for gesture handling)
 53→  translateY: ReturnType<typeof useSharedValue<number>>;
 54→  activeIndexShared: ReturnType<typeof useSharedValue<number>>;
 55→  getPageAnimatedStyle: ReturnType<typeof usePageAnimatedStyle>;
 56→  setActiveIndexInternal: (index: number) => void;
 57→
 58→  // Audio URLs for current page
 59→  narrationUrl: string | null;
 60→  soundscapeUrl: string | null;
 61→}
 62→
 63→const ReaderContext = createContext<ReaderContextValue | null>(null);
 64→
 65→interface ReaderProviderProps {
 66→  bookId: string;
 67→  children: ReactNode;
 68→}
 69→
 70→export function ReaderProvider({ bookId, children }: ReaderProviderProps) {
 71→  const router = useRouter();
 72→
 73→  // Data
 74→  const { data: readerData, isLoading, error } = useReaderData(bookId);
 75→  const { data: savedProgress } = useReadingProgress(bookId);
 76→
 77→  // State
 78→  const [activeIndex, setActiveIndex] = useState(0);
 79→  const [isUIVisible, setIsUIVisible] = useState(true);
 80→  const progressRestoredRef = useRef(false);
 81→
 82→  // Shared values for gestures
 83→  const translateY = useSharedValue(0);
 84→  const activeIndexShared = useSharedValue(0);
 85→  const getPageAnimatedStyle = usePageAnimatedStyle(translateY, activeIndexShared);
 86→
 87→  // Audio
 88→  const {
 89→    narrationState,
 90→    loadNarration,
 91→    playNarration,
 92→    pauseNarration,
 93→    soundscapeState,
 94→    loadSoundscape,
 95→    playSoundscape,
 96→    pauseSoundscape,
 97→    crossfadeSoundscape,
 98→    fadeOutSoundscape,
 99→    cleanup,
100→  } = useAudioPlayer();
101→
102→  const [isNarrationActive, setIsNarrationActive] = useState(false);
103→  const [isSoundscapeActive, setIsSoundscapeActive] = useState(false);
104→
105→  // Preferences
106→  const { preferences } = useLocalPreferences();
107→  const introFadeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
108→  const introFadedPages = useRef(new Set<number>());
109→
110→  // Derived
111→  const pages = useMemo(
112→    () => [...(readerData?.pages ?? [])].sort((a, b) => a.pageNumber - b.pageNumber),
113→    [readerData?.pages]
114→  );
115→  const totalPages = pages.length;
116→  const currentPage = pages[activeIndex]?.pageNumber ?? 1;
117→  const pageData: PageData | undefined = pages[activeIndex];
118→  const progressPercent = totalPages > 0 ? ((activeIndex + 1) / totalPages) * 100 : 0;
119→
120→  const narrationAssignment = pageData?.assignments?.find((a) => a.audioType === 'narration');
121→  const soundscapeAssignment = pageData?.assignments?.find((a) => a.audioType === 'soundscape');
122→  const narrationUrl = narrationAssignment?.audioUrl || pageData?.narrationUrl || null;
123→  const soundscapeUrl = soundscapeAssignment?.audioUrl || null;
124→
125→  // Visible pages (virtualization window of ±1)
126→  const visiblePageIndices = useMemo(() => {
127→    const indices: number[] = [];
128→    for (let i = Math.max(0, activeIndex - 1); i <= Math.min(totalPages - 1, activeIndex + 1); i++) {
129→      indices.push(i);
130→    }
131→    return indices;
132→  }, [activeIndex, totalPages]);
133→
134→  // Auto-save progress
135→  useAutoSaveProgress({
136→    bookId,
137→    currentPage,
138→    totalPages,
139→    enabled: !isLoading && totalPages > 0,
140→  });
141→
142→  // Restore reading progress
143→  useEffect(() => {
144→    if (progressRestoredRef.current || isLoading || !readerData) return;
145→
146→    if (savedProgress?.currentPage && savedProgress.currentPage > 1 && savedProgress.currentPage <= totalPages) {
147→      const idx = pages.findIndex((p) => p.pageNumber === savedProgress.currentPage);
148→      if (idx > 0) {
149→        setActiveIndex(idx);
150→        activeIndexShared.value = idx;
151→      }
152→    }
153→    progressRestoredRef.current = true;
154→  }, [savedProgress, isLoading, readerData, totalPages, pages, activeIndexShared]);
155→
156→  // Load narration audio when page changes
157→  useEffect(() => {
158→    if (narrationUrl) {
159→      loadNarration(narrationUrl).then(() => {
160→        if (isNarrationActive) {
161→          playNarration();
162→        }
163→      });
164→    }
165→    // eslint-disable-next-line react-hooks/exhaustive-deps
166→  }, [narrationUrl]);
167→
168→  // Handle soundscape changes with crossfade
169→  const prevSoundscapeUrl = useRef<string | null>(null);
170→  useEffect(() => {
171→    if (!soundscapeUrl) return;
172→
173→    if (prevSoundscapeUrl.current && prevSoundscapeUrl.current !== soundscapeUrl && isSoundscapeActive) {
174→      crossfadeSoundscape(soundscapeUrl);
175→    } else if (!prevSoundscapeUrl.current || prevSoundscapeUrl.current !== soundscapeUrl) {
176→      loadSoundscape(soundscapeUrl).then(() => {
177→        if (isSoundscapeActive) playSoundscape();
178→      });
179→    }
180→    prevSoundscapeUrl.current = soundscapeUrl;
181→    // eslint-disable-next-line react-hooks/exhaustive-deps
182→  }, [soundscapeUrl]);
183→
184→  // Intro-only mode: fade out after 10 seconds
185→  useEffect(() => {
186→    if (introFadeTimerRef.current) {
187→      clearTimeout(introFadeTimerRef.current);
188→      introFadeTimerRef.current = null;
189→    }
190→
191→    if (
192→      preferences.soundscapeMode === 'intro-only' &&
193→      isSoundscapeActive &&
194→      soundscapeUrl &&
195→      !introFadedPages.current.has(currentPage)
196→    ) {
197→      introFadeTimerRef.current = setTimeout(() => {
198→        introFadedPages.current.add(currentPage);
199→        fadeOutSoundscape(3000).then(() => {
200→          setIsSoundscapeActive(false);
201→        });
202→      }, 10000);
203→    }
204→
205→    return () => {
206→      if (introFadeTimerRef.current) clearTimeout(introFadeTimerRef.current);
207→    };
208→  }, [currentPage, preferences.soundscapeMode, isSoundscapeActive, soundscapeUrl, fadeOutSoundscape]);
209→
210→  // Cleanup on unmount
211→  useEffect(() => {
212→    return () => {
213→      cleanup();
214→    };
215→    // eslint-disable-next-line react-hooks/exhaustive-deps
216→  }, []);
217→
218→  // Actions
219→  const goToPage = useCallback((index: number) => {
220→    if (index >= 0 && index < totalPages) {
221→      setActiveIndex(index);
222→      activeIndexShared.value = index;
223→      translateY.value = 0;
224→      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
225→    }
226→  }, [totalPages, activeIndexShared, translateY]);
227→
228→  const toggleNarration = useCallback(async () => {
229→    if (isNarrationActive) {
230→      await pauseNarration();
231→      setIsNarrationActive(false);
232→    } else if (narrationUrl) {
233→      await playNarration();
234→      setIsNarrationActive(true);
235→    }
236→  }, [isNarrationActive, narrationUrl, playNarration, pauseNarration]);
237→
238→  const toggleSoundscape = useCallback(async () => {
239→    if (isSoundscapeActive) {
240→      await pauseSoundscape();
241→      setIsSoundscapeActive(false);
242→    } else if (soundscapeUrl) {
243→      await playSoundscape();
244→      setIsSoundscapeActive(true);
245→    }
246→  }, [isSoundscapeActive, soundscapeUrl, playSoundscape, pauseSoundscape]);
247→
248→  const handleClose = useCallback(() => {
249→    cleanup();
250→    router.back();
251→  }, [router, cleanup]);
252→
253→  // Internal setter for gesture handling
254→  const setActiveIndexInternal = useCallback((index: number) => {
255→    setActiveIndex(index);
256→    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
257→  }, []);
258→
259→  // UI visibility actions
260→  const toggleUI = useCallback(() => {
261→    setIsUIVisible((prev) => {
262→      const newValue = !prev;
263→      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
264→      return newValue;
265→    });
266→  }, []);
267→
268→  const showUI = useCallback(() => {
269→    setIsUIVisible(true);
270→  }, []);
271→
272→  const hideUI = useCallback(() => {
273→    setIsUIVisible(false);
274→  }, []);
275→
276→  const value: ReaderContextValue = {
277→    // Page state
278→    activeIndex,
279→    totalPages,
280→    currentPage,
281→    progressPercent,
282→    pages,
283→
284→    // Audio state
285→    isNarrationActive,
286→    isSoundscapeActive,
287→    narrationState,
288→    soundscapeState,
289→
290→    // UI visibility state
291→    isUIVisible,
292→
293→    // Actions
294→    goToPage,
295→    toggleNarration,
296→    toggleSoundscape,
297→    handleClose,
298→    toggleUI,
299→    showUI,
300→    hideUI,
301→
302→    // Data
303→    readerData,
304→    isLoading,
305→    error,
306→
307→    // Utility
308→    visiblePageIndices,
309→
310→    // Internal
311→    translateY,
312→    activeIndexShared,
313→    getPageAnimatedStyle,
314→    setActiveIndexInternal,
315→
316→    // Audio URLs
317→    narrationUrl,
318→    soundscapeUrl,
319→  };
320→
321→  return <ReaderContext.Provider value={value}>{children}</ReaderContext.Provider>;
322→}
323→
324→export function useReader() {
325→  const context = useContext(ReaderContext);
326→  if (!context) {
327→    throw new Error('useReader must be used within a ReaderProvider');
328→  }
329→  return context;
330→}
