 42→/**
 43→ * Resolve a font family and weight to the specific font variant name
 44→ */
 45→export function resolveFont(family: string, weight: number): string {
 46→  const familyMap = FONT_MAP[family];
 47→  if (!familyMap) {
 48→    // Fallback to system font weight
 49→    return 'System';
 50→  }
 51→
 52→  // Normalize weight to a valid key
 53→  const normalizedWeight = familyMap[weight] ? weight : 400;
 54→  return familyMap[normalizedWeight] ?? familyMap[400] ?? 'System';
 55→}
 56→
 57→/**
 58→ * Calculate the rectangle for an image that maintains aspect ratio
 59→ * and fits within the given view dimensions (object-fit: contain behavior)
 60→ */
 61→export function computeContainedImageRect(
 62→  viewWidth: number,
 63→  viewHeight: number,
 64→  imageAspectRatio: number
 65→): { x: number; y: number; width: number; height: number } {
 66→  if (viewWidth <= 0 || viewHeight <= 0 || imageAspectRatio <= 0) {
 67→    return { x: 0, y: 0, width: 0, height: 0 };
 68→  }
 69→
 70→  const viewAspectRatio = viewWidth / viewHeight;
 71→
 72→  if (imageAspectRatio > viewAspectRatio) {
 73→    // Image is wider than view - constrain by width
 74→    const width = viewWidth;
 75→    const height = width / imageAspectRatio;
 76→    const y = (viewHeight - height) / 2;
 77→    return { x: 0, y, width, height };
 78→  } else {
 79→    // Image is taller than view - constrain by height
 80→    const height = viewHeight;
 81→    const width = height * imageAspectRatio;
 82→    const x = (viewWidth - width) / 2;
 83→    return { x, y: 0, width, height };
 84→  }
 85→}
 86→
 87→/**
 88→ * Derive the full text content from all overlay elements
 89→ * Concatenates element texts with a space separator
 90→ */
 91→export function deriveTextContent(overlay: TextOverlayConfig): string {
 92→  if (!overlay || !Array.isArray(overlay.elements)) {
 93→    return '';
 94→  }
 95→
 96→  return overlay.elements
 97→    .filter((el): el is TextElement => el && typeof el.text === 'string')
 98→    .map(el => el.text.trim())
 99→    .filter(text => text.length > 0)
100→    .join(' ');
101→}
102→
103→/**
104→ * Calculate the starting word index for each text element
105→ * Returns a map of element ID to its starting word position
106→ */
107→export function calculateWordStartsByElementId(
108→  overlay: TextOverlayConfig
109→): Map<string, number> {
110→  const wordStarts = new Map<string, number>();
111→
112→  if (!overlay || !Array.isArray(overlay.elements)) {
113→    return wordStarts;
114→  }
115→
116→  let wordCount = 0;
117→
118→  for (const element of overlay.elements) {
119→    if (!element || typeof element.text !== 'string') {
120→      continue;
121→    }
122→
123→    wordStarts.set(element.id, wordCount);
124→
125→    // Count words in this element's text
126→    const trimmed = element.text.trim();
127→    if (trimmed.length > 0) {
128→      const words = trimmed.split(/\s+/);
129→      wordCount += words.length;
130→    }
131→  }
132→
133→  return wordStarts;
134→}
