135→class PageData {
136→  final String id;
137→  final int pageNumber;
138→  final String? textContent;
139→  final TextOverlayConfig? overlay;
140→  final String? imageUrl;
141→  final String? narrationUrl;
142→  final String? soundscapeUrl;
143→  final String? compositedImageUrl;
144→  final List<WordTimestamp>? narrationTimestamps;
145→
146→  const PageData({
147→    required this.id,
148→    required this.pageNumber,
149→    this.textContent,
150→    this.overlay,
151→    this.imageUrl,
152→    this.narrationUrl,
153→    this.soundscapeUrl,
154→    this.compositedImageUrl,
155→    this.narrationTimestamps,
156→  });
157→
158→  factory PageData.fromJson(Map<String, dynamic> json) {
159→    final rawTimestamps =
160→        json['narration_timestamps'] ?? json['narrationTimestamps'];
161→    final timestamps = rawTimestamps is List
162→        ? rawTimestamps
163→              .whereType<Map<String, dynamic>>()
164→              .map(WordTimestamp.fromJson)
165→              .toList()
166→        : null;
167→
168→    final overlayJson = json['text_overlay'];
169→
170→    // Soundscape URL is derived from the nested scenes -> soundscapes relation.
171→    // Prefer admin-approved soundscapes, fall back to first available.
172→    String? soundscapeUrl;
173→    final scenesData = json['scenes'];
174→    if (scenesData is Map<String, dynamic>) {
175→      final rawSoundscapes = scenesData['soundscapes'];
176→      if (rawSoundscapes is List && rawSoundscapes.isNotEmpty) {
177→        final soundscapes = rawSoundscapes
178→            .whereType<Map<String, dynamic>>()
179→            .toList();
180→        final approved = soundscapes
181→            .where((s) => s['admin_approved'] == true)
182→            .toList();
183→        final chosen = approved.isNotEmpty ? approved.first : soundscapes.first;
184→        soundscapeUrl = chosen['audio_url'] as String?;
185→      }
186→    }
187→
188→    return PageData(
189→      id: json['id']?.toString() ?? '',
190→      pageNumber: _parsePageNumber(json),
191→      textContent:
192→          json['text_content'] as String? ?? json['textContent'] as String?,
193→      overlay: overlayJson is Map<String, dynamic>
194→          ? TextOverlayConfig.fromJson(overlayJson)
195→          : null,
196→      imageUrl: json['image_url'] as String? ?? json['imageUrl'] as String?,
197→      narrationUrl:
198→          json['narration_url'] as String? ?? json['narrationUrl'] as String?,
199→      soundscapeUrl: soundscapeUrl,
200→      compositedImageUrl:
201→          json['composited_image_url'] as String? ??
202→          json['compositedImageUrl'] as String?,
203→      narrationTimestamps: timestamps,
204→    );
205→  }
206→}
