208→class Book {
209→  final String id;
210→  final String title;
211→  final String? author;
212→  final String? coverUrl;
213→  final List<PageData> pages;
214→
215→  const Book({
216→    required this.id,
217→    required this.title,
218→    this.author,
219→    this.coverUrl,
220→    required this.pages,
221→  });
222→
223→  factory Book.fromJson(Map<String, dynamic> json) {
224→    final parsedPages = (json['pages'] as List<dynamic>? ?? <dynamic>[])
225→        .whereType<Map<String, dynamic>>()
226→        .map(PageData.fromJson)
227→        .toList();
228→
229→    final pages = _sortedPages(parsedPages);
230→    assert(() {
231→      if (_isDifferentOrder(parsedPages, pages)) {
232→        debugPrint(
233→          '[Book.fromJson] Incoming page order was unsorted for book '
234→          '${json['id'] ?? ''}. Applying deterministic sort by pageNumber/id.',
235→        );
236→      }
237→      return true;
238→    }());
239→
240→    return Book(
241→      id: json['id']?.toString() ?? '',
242→      title: json['title'] as String? ?? '',
243→      author: json['author'] as String?,
244→      coverUrl: json['cover_url'] as String? ?? json['coverUrl'] as String?,
245→      pages: pages,
246→    );
247→  }
248→}
249→
250→const int _invalidPageNumber = 1 << 30;
251→
252→int _parsePageNumber(Map<String, dynamic> json) {
253→  final rawPageNumber = json['page_number'] ?? json['pageNumber'];
254→  if (rawPageNumber is num) {
255→    final pageNumber = rawPageNumber.toInt();
256→    return pageNumber > 0 ? pageNumber : _invalidPageNumber;
257→  }
258→  if (rawPageNumber is String) {
259→    final pageNumber = int.tryParse(rawPageNumber);
260→    if (pageNumber == null || pageNumber <= 0) {
261→      return _invalidPageNumber;
262→    }
263→    return pageNumber;
264→  }
265→  return _invalidPageNumber;
266→}
267→
268→List<PageData> _sortedPages(List<PageData> pages) {
269→  final indexedPages = pages.asMap().entries.toList();
270→  indexedPages.sort((a, b) {
271→    final pageNumberCompare = a.value.pageNumber.compareTo(b.value.pageNumber);
272→    if (pageNumberCompare != 0) {
273→      return pageNumberCompare;
274→    }
275→
276→    final idCompare = a.value.id.compareTo(b.value.id);
277→    if (idCompare != 0) {
278→      return idCompare;
279→    }
280→
281→    return a.key.compareTo(b.key);
282→  });
283→
284→  return indexedPages.map((entry) => entry.value).toList(growable: false);
285→}
286→
287→bool _isDifferentOrder(List<PageData> original, List<PageData> sorted) {
288→  if (identical(original, sorted)) {
289→    return false;
290→  }
291→  if (original.length != sorted.length) {
292→    return true;
293→  }
294→  for (var i = 0; i < original.length; i++) {
295→    if (!identical(original[i], sorted[i])) {
296→      return true;
297→    }
298→  }
299→  return false;
300→}
