  1→import 'package:flutter/material.dart';
  2→import 'package:flutter_animate/flutter_animate.dart';
  3→
  4→import '../../../data/models.dart';
  5→import 'text_overlay_utils.dart';
  6→
  7→class OverlayTextElement extends StatelessWidget {
  8→  final TextElement element;
  9→  final int elementIndex;
 10→  final Size imageSize;
 11→  final int wordStartIndex;
 12→  final int activeWordIndex;
 13→  final bool isActive;
 14→  final void Function(String word, int globalIndex)? onWordTap;
 15→
 16→  const OverlayTextElement({
 17→    super.key,
 18→    required this.element,
 19→    required this.elementIndex,
 20→    required this.imageSize,
 21→    required this.wordStartIndex,
 22→    required this.activeWordIndex,
 23→    required this.isActive,
 24→    this.onWordTap,
 25→  });
 26→
 27→  @override
 28→  Widget build(BuildContext context) {
 29→    final left = (element.x / 100) * imageSize.width;
 30→    final top = (element.y / 100) * imageSize.height;
 31→    final width = (element.width / 100) * imageSize.width;
 32→    final fontSize = (element.fontSize / 100) * imageSize.height;
 33→
 34→    final baseStyle =
 35→        resolveFontStyle(
 36→          element.fontFamily,
 37→          element.fontWeight,
 38→          fontSize,
 39→          parseHexColor(element.color),
 40→        ).copyWith(
 41→          height: 1.3,
 42→          shadows: element.shadow == null
 43→              ? null
 44→              : [
 45→                  Shadow(
 46→                    color: parseHexColor(
 47→                      element.shadow!.color,
 48→                      fallback: Colors.black,
 49→                    ),
 50→                    offset: Offset(element.shadow!.x, element.shadow!.y),
 51→                    blurRadius: element.shadow!.blur,
 52→                  ),
 53→                ],
 54→        );
 55→
 56→    final background = element.background;
 57→
 58→    Widget content = RichText(
 59→      textAlign: resolveTextAlign(element.textAlign),
 60→      text: TextSpan(style: baseStyle, children: _buildSpans(baseStyle)),
 61→    );
 62→
 63→    if (background != null) {
 64→      content = Container(
 65→        padding: EdgeInsets.all(background.padding ?? 0),
 66→        decoration: BoxDecoration(
 67→          color: parseHexColor(background.color, fallback: Colors.transparent),
 68→          borderRadius: BorderRadius.circular(background.borderRadius ?? 0),
 69→        ),
 70→        child: content,
 71→      );
 72→    }
 73→
 74→    final rotated = element.rotation != 0
 75→        ? Transform.rotate(
 76→            angle: (element.rotation * 3.141592653589793) / 180,
 77→            child: content,
 78→          )
 79→        : content;
 80→
 81→    return Positioned(
 82→      left: left,
 83→      top: top,
 84→      width: width,
 85→      child: rotated
 86→          .animate(target: isActive ? 1 : 0)
 87→          .fadeIn(
 88→            duration: 350.ms,
 89→            delay: Duration(milliseconds: 180 + elementIndex * 40),
 90→          )
 91→          .slideY(
 92→            begin: 0.12,
 93→            end: 0,
 94→            duration: 350.ms,
 95→            delay: Duration(milliseconds: 180 + elementIndex * 40),
 96→          ),
 97→    );
 98→  }
 99→
100→  List<InlineSpan> _buildSpans(TextStyle baseStyle) {
101→    final tokens = RegExp(
102→      r'\s+|\S+',
103→    ).allMatches(element.text).map((m) => m.group(0) ?? '').toList();
104→    final spans = <InlineSpan>[];
105→    var currentWordIndex = wordStartIndex;
106→
107→    for (final token in tokens) {
108→      if (token.trim().isEmpty) {
109→        spans.add(TextSpan(text: token, style: baseStyle));
110→        continue;
111→      }
112→
113→      final globalIndex = currentWordIndex;
114→      currentWordIndex += 1;
115→      final isHighlighted = globalIndex == activeWordIndex;
116→
117→      final wordText = Text(
118→        token,
119→        style: isHighlighted
120→            ? baseStyle.copyWith(
121→                backgroundColor: const Color.fromRGBO(212, 237, 188, 0.8),
122→                fontWeight: FontWeight.w700,
123→              )
124→            : baseStyle,
125→      );
126→
127→      if (onWordTap == null) {
128→        spans.add(
129→          WidgetSpan(
130→            child: wordText,
131→            alignment: PlaceholderAlignment.baseline,
132→            baseline: TextBaseline.alphabetic,
133→          ),
134→        );
135→        continue;
136→      }
137→
138→      spans.add(
139→        WidgetSpan(
140→          alignment: PlaceholderAlignment.baseline,
141→          baseline: TextBaseline.alphabetic,
142→          child: GestureDetector(
143→            behavior: HitTestBehavior.opaque,
144→            onTap: () => onWordTap?.call(token, globalIndex),
145→            child: wordText,
146→          ),
147→        ),
148→      );
149→    }
150→
151→    return spans;
152→  }
153→}
