  1→import React, { useEffect } from 'react';
  2→import { Text, View, StyleSheet, Pressable, type TextStyle, type ViewStyle } from 'react-native';
  3→import Animated, {
  4→  useSharedValue,
  5→  useAnimatedStyle,
  6→  withTiming,
  7→  withDelay,
  8→  Easing,
  9→} from 'react-native-reanimated';
 10→import type { TextElement } from '@/types';
 11→import { resolveFont } from '@/lib/textOverlay';
 12→
 13→interface OverlayTextElementProps {
 14→  element: TextElement;
 15→  elementIndex: number;
 16→  imageWidth: number;
 17→  imageHeight: number;
 18→  wordStartIndex: number;
 19→  activeWordIndex?: number;
 20→  pronouncingWordIndex?: number | null;
 21→  isActive: boolean;
 22→  onWordTap?: (word: string, globalIndex: number) => void;
 23→}
 24→
 25→export function OverlayTextElement({
 26→  element,
 27→  elementIndex,
 28→  imageWidth,
 29→  imageHeight,
 30→  wordStartIndex,
 31→  activeWordIndex,
 32→  pronouncingWordIndex,
 33→  isActive,
 34→  onWordTap,
 35→}: OverlayTextElementProps) {
 36→  // Animation value
 37→  const progress = useSharedValue(0);
 38→
 39→  // Stagger entrance animation
 40→  useEffect(() => {
 41→    if (isActive) {
 42→      const delay = 180 + elementIndex * 40;
 43→      progress.value = withDelay(
 44→        delay,
 45→        withTiming(1, {
 46→          duration: 350,
 47→          easing: Easing.out(Easing.ease),
 48→        })
 49→      );
 50→    } else {
 51→      // Reset immediately when inactive
 52→      progress.value = 0;
 53→    }
 54→  }, [isActive, elementIndex, progress]);
 55→
 56→  // Animated style for container
 57→  const animatedStyle = useAnimatedStyle(() => ({
 58→    opacity: progress.value,
 59→    transform: [{ translateY: (1 - progress.value) * 16 }],
 60→  }));
 61→
 62→  // Convert percentage to pixels
 63→  const x = (element.x / 100) * imageWidth;
 64→  const y = (element.y / 100) * imageHeight;
 65→  const width = (element.width / 100) * imageWidth;
 66→
 67→  // Resolve font family (weight encoded in name)
 68→  const fontFamily = resolveFont(element.fontFamily, element.fontWeight);
 69→
 70→  // Calculate font size based on image height (assuming 100% = full image height)
 71→  const fontSize = (element.fontSize / 100) * imageHeight;
 72→
 73→  // Build text style
 74→  const textStyle: TextStyle = {
 75→    fontFamily,
 76→    fontSize,
 77→    color: element.color,
 78→    textAlign: element.textAlign,
 79→    lineHeight: fontSize * 1.3,
 80→  };
 81→
 82→  // Shadow style
 83→  const shadowStyle: TextStyle = element.shadow
 84→    ? {
 85→        textShadowColor: element.shadow.color,
 86→        textShadowOffset: { width: element.shadow.x, height: element.shadow.y },
 87→        textShadowRadius: element.shadow.blur,
 88→      }
 89→    : {};
 90→
 91→  // Container styles
 92→  const containerStyle: ViewStyle = {
 93→    position: 'absolute',
 94→    left: x,
 95→    top: y,
 96→    width,
 97→    transform: element.rotation !== 0 ? [{ rotate: `${element.rotation}deg` }] : undefined,
 98→  };
 99→
100→  // Background container style
101→  const backgroundStyle: ViewStyle = element.background
102→    ? {
103→        backgroundColor: element.background.color,
104→        padding: element.background.padding || 0,
105→        borderRadius: element.background.borderRadius || 0,
106→      }
107→    : {};
108→
109→  // Split text into tokens (preserving whitespace)
110→  const tokens = element.text.split(/(\s+)/);
111→
112→  // Check if a word is highlighted
113→  const isWordHighlighted = (globalIndex: number): boolean => {
114→    if (activeWordIndex !== undefined && globalIndex === activeWordIndex) {
115→      return true;
116→    }
117→    if (pronouncingWordIndex !== null && pronouncingWordIndex !== undefined && globalIndex === pronouncingWordIndex) {
118→      return true;
119→    }
120→    return false;
121→  };
122→
123→  // Word index tracker
124→  let currentWordIndex = wordStartIndex;
125→
126→  return (
127→    <Animated.View style={[containerStyle, animatedStyle]} pointerEvents="box-none">
128→      <View style={backgroundStyle}>
129→        <Text style={[textStyle, shadowStyle]}>
130→          {tokens.map((token, tokenIndex) => {
131→            // Check if token is whitespace
132→            if (/^\s+$/.test(token)) {
133→              return token;
134→            }
135→
136→            // It's a word
137→            const globalIndex = currentWordIndex;
138→            const isHighlighted = isWordHighlighted(globalIndex);
139→            currentWordIndex++;
140→
141→            const wordStyle: TextStyle = isHighlighted
142→              ? {
143→                  backgroundColor: 'rgba(212, 237, 188, 0.8)',
144→                  borderRadius: 4,
145→                  paddingHorizontal: 2,
146→                }
147→              : {};
148→
149→            if (onWordTap) {
150→              return (
151→                <Pressable
152→                  key={tokenIndex}
153→                  onPress={() => onWordTap(token, globalIndex)}
154→                  style={styles.pressableWord}
155→                >
156→                  <Text style={[textStyle, shadowStyle, wordStyle]}>{token}</Text>
157→                </Pressable>
158→              );
159→            }
160→
161→            return (
162→              <Text key={tokenIndex} style={[textStyle, shadowStyle, wordStyle]}>
163→                {token}
164→              </Text>
165→            );
166→          })}
167→        </Text>
168→      </View>
169→    </Animated.View>
170→  );
171→}
172→
173→const styles = StyleSheet.create({
174→  pressableWord: {
175→    display: 'flex',
176→  },
177→});
