  6→Rect computeContainedImageRect({
  7→  required Size container,
  8→  required Size sourceImage,
  9→}) {
 10→  if (container.width <= 0 ||
 11→      container.height <= 0 ||
 12→      sourceImage.width <= 0 ||
 13→      sourceImage.height <= 0) {
 14→    return Rect.zero;
 15→  }
 16→
 17→  final containerAspect = container.width / container.height;
 18→  final imageAspect = sourceImage.width / sourceImage.height;
 19→
 20→  if (imageAspect > containerAspect) {
 21→    final width = container.width;
 22→    final height = width / imageAspect;
 23→    final y = (container.height - height) / 2;
 24→    return Rect.fromLTWH(0, y, width, height);
 25→  }
 26→
 27→  final height = container.height;
 28→  final width = height * imageAspect;
 29→  final x = (container.width - width) / 2;
 30→  return Rect.fromLTWH(x, 0, width, height);
 31→}
 32→
 33→int computeActiveWordIndex(
 34→  List<WordTimestamp>? timestamps,
 35→  Duration currentPosition,
 36→) {
 37→  if (timestamps == null || timestamps.isEmpty) {
 38→    return -1;
 39→  }
 40→
 41→  final currentTime = currentPosition.inMilliseconds / 1000;
 42→  var foundIndex = -1;
 43→
 44→  for (var i = 0; i < timestamps.length; i++) {
 45→    final word = timestamps[i];
 46→    final nextWord = i + 1 < timestamps.length ? timestamps[i + 1] : null;
 47→
 48→    if (currentTime >= word.start && currentTime <= word.end) {
 49→      foundIndex = i;
 50→      break;
 51→    }
 52→    if (nextWord != null &&
 53→        currentTime > word.end &&
 54→        currentTime < nextWord.start) {
 55→      foundIndex = i;
 56→      break;
 57→    }
 58→    if (nextWord == null && currentTime >= word.start) {
 59→      foundIndex = i;
 60→      break;
 61→    }
 62→    if (currentTime > word.end) {
 63→      foundIndex = i;
 64→    }
 65→  }
 66→
 67→  return foundIndex;
 68→}
 69→
 70→Map<String, int> calculateWordStartsByElementId(TextOverlayConfig overlay) {
 71→  final map = <String, int>{};
 72→  var wordCount = 0;
 73→
 74→  for (final element in overlay.elements) {
 75→    map[element.id] = wordCount;
 76→    final trimmed = element.text.trim();
 77→    if (trimmed.isNotEmpty) {
 78→      wordCount += trimmed.split(RegExp(r'\s+')).length;
 79→    }
 80→  }
 81→
 82→  return map;
 83→}
 84→
 85→Color parseHexColor(String value, {Color fallback = Colors.white}) {
 86→  var hex = value.trim();
 87→  if (hex.isEmpty) {
 88→    return fallback;
 89→  }
 90→  if (hex.startsWith('#')) {
 91→    hex = hex.substring(1);
 92→  }
 93→  if (hex.length == 6) {
 94→    hex = 'FF$hex';
 95→  }
 96→  if (hex.length != 8) {
 97→    return fallback;
 98→  }
 99→  final intValue = int.tryParse(hex, radix: 16);
100→  if (intValue == null) {
101→    return fallback;
102→  }
103→  return Color(intValue);
104→}
105→
106→TextAlign resolveTextAlign(String value) {
107→  switch (value) {
108→    case 'center':
109→      return TextAlign.center;
110→    case 'right':
111→      return TextAlign.right;
112→    default:
113→      return TextAlign.left;
114→  }
115→}
116→
117→TextStyle resolveFontStyle(
118→  String family,
119→  int weight,
120→  double size,
121→  Color color,
122→) {
123→  final fw = FontWeight.values.firstWhere(
124→    (w) => w.index * 100 == weight,
125→    orElse: () => FontWeight.w400,
126→  );
127→
128→  switch (family) {
129→    case 'Lora':
130→      return GoogleFonts.lora(fontSize: size, color: color, fontWeight: fw);
131→    case 'Playfair Display':
132→      return GoogleFonts.playfairDisplay(
133→        fontSize: size,
134→        color: color,
135→        fontWeight: fw,
136→      );
137→    case 'JetBrains Mono':
138→      return GoogleFonts.jetBrainsMono(
139→        fontSize: size,
140→        color: color,
141→        fontWeight: fw,
142→      );
143→    case 'Gaegu':
144→      return GoogleFonts.gaegu(fontSize: size, color: color, fontWeight: fw);
145→    default:
146→      return GoogleFonts.inter(fontSize: size, color: color, fontWeight: fw);
147→  }
148→}
