  1→import React, { useState, useCallback, useMemo } from 'react';
  2→import { View, StyleSheet, Dimensions, type LayoutChangeEvent } from 'react-native';
  3→import { Image, type ImageLoadEventData } from 'expo-image';
  4→import { LinearGradient } from 'expo-linear-gradient';
  5→import Animated, { type AnimatedStyle } from 'react-native-reanimated';
  6→import { WordHighlighter } from './WordHighlighter';
  7→import { OverlayTextLayer } from './reader/OverlayTextLayer';
  8→import type { PageData, WordTimestamp } from '@/types';
  9→import { useThemeColors, fonts } from '@/lib/theme';
 10→import { computeContainedImageRect } from '@/lib/textOverlay';
 11→
 12→const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get('window');
 13→
 14→type Props = {
 15→  page: PageData;
 16→  activeWordIndex: number;
 17→  isActive: boolean;
 18→  animatedStyle: AnimatedStyle;
 19→  narrationTimestamps: WordTimestamp[] | null;
 20→  currentPositionMs: number;
 21→  isNarrationPlaying: boolean;
 22→  onWordTap?: (word: string, globalIndex: number) => void;
 23→  pronouncingWordIndex?: number;
 24→};
 25→
 26→export const PageRenderer = React.memo(function PageRenderer({
 27→  page,
 28→  isActive,
 29→  animatedStyle,
 30→  narrationTimestamps,
 31→  currentPositionMs,
 32→  isNarrationPlaying,
 33→  onWordTap,
 34→  pronouncingWordIndex,
 35→}: Props) {
 36→  const colors = useThemeColors();
 37→
 38→  // Image measurement state
 39→  const [imageDimensions, setImageDimensions] = useState({ width: 0, height: 0 });
 40→  const [sourceImageDimensions, setSourceImageDimensions] = useState<{ width: number; height: number } | null>(null);
 41→
 42→  // Handlers for image measurement
 43→  const onImageLayout = useCallback((event: LayoutChangeEvent) => {
 44→    const { width, height } = event.nativeEvent.layout;
 45→    setImageDimensions({ width, height });
 46→  }, []);
 47→
 48→  const onImageLoad = useCallback((event: ImageLoadEventData) => {
 49→    setSourceImageDimensions({
 50→      width: event.source.width,
 51→      height: event.source.height,
 52→    });
 53→  }, []);
 54→
 55→  // Determine display mode
 56→  const hasOverlay = (page.overlay?.elements?.length ?? 0) > 0;
 57→  const hasComposited = !!(page as any).compositedImageUrl;
 58→  const hasFallback = !!page.textContent && !!page.imageUrl;
 59→
 60→  // Compute contained image rect when using overlay mode
 61→  const containedRect = useMemo(() => {
 62→    if (!hasOverlay || !sourceImageDimensions) return null;
 63→    return computeContainedImageRect(
 64→      imageDimensions.width,
 65→      imageDimensions.height,
 66→      sourceImageDimensions.width / sourceImageDimensions.height
 67→    );
 68→  }, [hasOverlay, imageDimensions, sourceImageDimensions]);
 69→
 70→  // Calculate active word index from narration timestamps
 71→  const computedActiveWordIndex = useMemo(() => {
 72→    if (!isNarrationPlaying || !narrationTimestamps || narrationTimestamps.length === 0) return -1;
 73→
 74→    const currentTime = currentPositionMs / 1000;
 75→    let foundIndex = -1;
 76→
 77→    for (let i = 0; i < narrationTimestamps.length; i++) {
 78→      const wordData = narrationTimestamps[i];
 79→      const nextWord = narrationTimestamps[i + 1];
 80→
 81→      if (currentTime >= wordData.start && currentTime <= wordData.end) {
 82→        foundIndex = i;
 83→        break;
 84→      }
 85→      if (nextWord && currentTime > wordData.end && currentTime < nextWord.start) {
 86→        foundIndex = i;
 87→        break;
 88→      }
 89→      if (!nextWord && currentTime >= wordData.start) {
 90→        foundIndex = i;
 91→        break;
 92→      }
 93→      if (currentTime > wordData.end) {
 94→        foundIndex = i;
 95→      }
 96→    }
 97→
 98→    return foundIndex;
 99→  }, [currentPositionMs, narrationTimestamps, isNarrationPlaying]);
100→
101→  // Determine content fit based on mode
102→  const contentFit: 'cover' | 'contain' = hasOverlay ? 'contain' : 'cover';
103→
104→  return (
105→    <Animated.View style={[styles.page, animatedStyle]}>
106→      {/* View wrapper with onLayout for measurement */}
107→      <View style={styles.imageContainer} onLayout={onImageLayout}>
108→        {/* Full-bleed illustration */}
109→        {page.imageUrl ? (
110→          <Image
111→            source={{ uri: page.imageUrl }}
112→            style={styles.fullBleedImage}
113→            contentFit={contentFit}
114→            transition={isActive ? 300 : 0}
115→            onLoad={onImageLoad}
116→          />
117→        ) : (
118→          <View style={[styles.fullBleedImage, { backgroundColor: colors.readerCardBg }]} />
119→        )}
120→
121→        {/* DYNAMIC OVERLAY mode: Render OverlayTextLayer positioned at containedRect */}
122→        {hasOverlay && containedRect && page.overlay && (
123→          <View
124→            style={[
125→              styles.overlayLayer,
126→              {
127→                left: containedRect.x,
128→                top: containedRect.y,
129→                width: containedRect.width,
130→                height: containedRect.height,
131→              },
132→            ]}
133→          >
134→            <OverlayTextLayer
135→              overlay={page.overlay}
136→              imageWidth={containedRect.width}
137→              imageHeight={containedRect.height}
138→              activeWordIndex={computedActiveWordIndex}
139→              pronouncingWordIndex={pronouncingWordIndex}
140→              isActive={isActive}
141→              onWordTap={onWordTap}
142→            />
143→          </View>
144→        )}
145→
146→        {/* COMPOSITED mode: No additional overlay components needed */}
147→        {/* Image is already rendered above with contentFit="cover" */}
148→
149→        {/* FALLBACK mode: Gradient scrims + WordHighlighter at bottom */}
150→        {!hasOverlay && !hasComposited && hasFallback && page.textContent && (
151→          <>
152→            {/* Gradient scrim for text readability */}
153→            <LinearGradient
154→              colors={['transparent', 'rgba(0,0,0,0.5)', 'rgba(0,0,0,0.85)']}
155→              locations={[0, 0.3, 1]}
156→              style={styles.gradientScrim}
157→            />
158→            <LinearGradient
159→              colors={['transparent', 'rgba(0,0,0,0.3)']}
160→              locations={[0.5, 1]}
161→              style={[styles.gradientScrim, { height: SCREEN_HEIGHT * 0.25 }]}
162→            />
163→
164→            {/* Overlaid text at bottom */}
165→            <View style={styles.textOverlay}>
166→              <WordHighlighter
167→                text={page.textContent}
168→                timestamps={narrationTimestamps}
169→                currentPositionMs={currentPositionMs}
170→                isPlaying={isActive && isNarrationPlaying}
171→                isActive={isActive}
172→                overlayMode
173→              />
174→            </View>
175→          </>
176→        )}
177→
178→        {/* IMAGE ONLY mode: Just image, no text - already rendered above */}
179→      </View>
180→    </Animated.View>
181→  );
182→});
