 1→import { useCallback } from 'react';
 2→import { Dimensions } from 'react-native';
 3→import { useAnimatedStyle, SharedValue } from 'react-native-reanimated';
 4→
 5→const { height: SCREEN_HEIGHT } = Dimensions.get('window');
 6→
 7→/**
 8→ * Continuous scrollOffset architecture:
 9→ *
10→ * scrollOffset is a single SharedValue representing the total vertical scroll position.
11→ * At rest on page N, scrollOffset = -N * SCREEN_HEIGHT.
12→ *
13→ * Each page's position is derived from:
14→ *   pageTranslateY = scrollOffset + pageIndex * SCREEN_HEIGHT
15→ *
16→ * All easing, momentum (withDecay), and snap behaviour live in the gesture
17→ * handler that drives scrollOffset — the styles here are pure position math.
18→ */
19→export function usePageAnimatedStyle(
20→  scrollOffset: SharedValue<number>,
21→  activeIndexShared: SharedValue<number>
22→): (pageIndex: number) => ReturnType<typeof useAnimatedStyle> {
23→  return useCallback(
24→    (pageIndex: number) => {
25→      return useAnimatedStyle(() => {
26→        const activeIndex = activeIndexShared.value;
27→        const diff = pageIndex - activeIndex;
28→
29→        // Base position derived from continuous scroll offset
30→        const baseY = scrollOffset.value + pageIndex * SCREEN_HEIGHT;
31→
32→        // ── Active page (diff === 0) ──────────────────────────────
33→        // Tracks scrollOffset directly — no extra transform needed.
34→        if (diff === 0) {
35→          return {
36→            transform: [{ translateY: baseY }],
37→            opacity: 1,
38→            zIndex: 2,
39→          };
40→        }
41→
42→        // ── Next page (diff === 1) ────────────────────────────────
43→        // Sits at SCREEN_HEIGHT below when at rest, slides up as
44→        // scrollOffset decreases. No per-style easing — smoothness
45→        // comes from the scrollOffset animation itself.
46→        if (diff === 1) {
47→          return {
48→            transform: [{ translateY: baseY }],
49→            opacity: 1,
50→            zIndex: 3,
51→          };
52→        }
53→
54→        // ── Previous page (diff === -1) ───────────────────────────
55→        // Parallax: moves at 70% speed when above viewport, creating
56→        // a sense of depth — the previous page lags behind slightly.
57→        // Opacity fades to 0.25 as it moves fully above.
58→        if (diff === -1) {
59→          const parallaxY = baseY < 0 ? baseY * 0.7 : baseY;
60→
61→          // progress: 0 when page is at rest (baseY = 0), 1 when fully above
62→          const progress = Math.min(Math.max(-baseY / SCREEN_HEIGHT, 0), 1);
63→          const opacity = 1 - progress * 0.75; // fades from 1.0 → 0.25
64→
65→          return {
66→            transform: [{ translateY: parallaxY }],
67→            opacity,
68→            zIndex: 1,
69→          };
70→        }
71→
72→        // ── Off-screen pages (|diff| > 1) ─────────────────────────
73→        // Hidden and positioned out of view to avoid unnecessary rendering.
74→        return {
75→          transform: [{ translateY: diff > 0 ? SCREEN_HEIGHT : -SCREEN_HEIGHT }],
76→          opacity: 0,
77→          zIndex: 0,
78→        };
79→      });
80→    },
81→    [scrollOffset, activeIndexShared]
82→  );
83→}
