  3→const API_BASE = process.env.EXPO_PUBLIC_API_URL || 'http://localhost:3000';
  4→
  5→type RequestOptions = Omit<RequestInit, 'headers'> & {
  6→  params?: Record<string, string>;
  7→};
  8→
  9→async function request<T>(path: string, options: RequestOptions = {}): Promise<T> {
 10→  const { params, ...fetchOptions } = options;
 11→
 12→  let url = `${API_BASE}${path}`;
 13→  if (params) {
 14→    const searchParams = new URLSearchParams(params);
 15→    url += `?${searchParams.toString()}`;
 16→  }
 17→
 18→  const headers: Record<string, string> = {
 19→    'Content-Type': 'application/json',
 20→  };
 21→
 22→  const response = await fetch(url, {
 23→    ...fetchOptions,
 24→    headers,
 25→  });
 26→
 27→  if (!response.ok) {
 28→    const payload = await response.json().catch(() => ({}));
 29→    throw new Error(payload?.error || `Request failed: ${response.status}`);
 30→  }
 31→
 32→  return response.json() as Promise<T>;
 33→}
