100→  List<InlineSpan> _buildSpans(TextStyle baseStyle) {
101→    final tokens = RegExp(
102→      r'\s+|\S+',
103→    ).allMatches(element.text).map((m) => m.group(0) ?? '').toList();
104→    final spans = <InlineSpan>[];
105→    var currentWordIndex = wordStartIndex;
106→
107→    for (final token in tokens) {
108→      if (token.trim().isEmpty) {
109→        spans.add(TextSpan(text: token, style: baseStyle));
110→        continue;
111→      }
112→
113→      final globalIndex = currentWordIndex;
114→      currentWordIndex += 1;
115→      final isHighlighted = globalIndex == activeWordIndex;
116→
117→      final wordText = Text(
118→        token,
119→        style: isHighlighted
120→            ? baseStyle.copyWith(
121→                backgroundColor: const Color.fromRGBO(212, 237, 188, 0.8),
122→                fontWeight: FontWeight.w700,
123→              )
124→            : baseStyle,
125→      );
126→
127→      if (onWordTap == null) {
128→        spans.add(
129→          WidgetSpan(
130→            child: wordText,
131→            alignment: PlaceholderAlignment.baseline,
132→            baseline: TextBaseline.alphabetic,
